(window.MAP_DATA = window.MAP_DATA || {})["language_7"] = {"grade":7,"subject":"language","units":[{"id":"R5","n":5,"title":"RIT 5","goal":"RIT","band":"191–200","skills":["Identifies phrases and clauses and their functions","Recognizes complete sentences, fragments and run-ons","Uses the correct pronoun case","Forms irregular past-tense and past-participle verbs"],"vocab":[],"sets":[{"p":0,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which sentence first states Abdulaziz’s claim?","o":["sentence 1","sentence 2","sentence 4","sentence 5"],"k":"C","sk":"States a clear claim or thesis","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which transition BEST begins sentence 6 to respond to the counterclaim?","o":["However,","Similarly,","Therefore,","For instance,"],"k":"A","sk":"Acknowledges and answers an opposing claim","b":"191–200","g":"WR"}],"set":"1"},{"p":1,"goal":"WR","items":[{"n":1,"t":"mc","s":"How is Jana’s report mainly organized?","o":["by explaining the causes and effects of a problem","by describing the steps for floating in salt water","by comparing the Dead Sea with the Red Sea","by telling a story in the order that events happened"],"k":"A","sk":"Puts sentences or events in a logical order","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which word in sentence 3 signals a contrast with sentence 2?","o":["past","surface","dropped","however"],"k":"D","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"}],"set":"2"},{"p":2,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which word could replace “walked” in sentence 4 to show that Reema is nervous?","o":["skipped","stumbled","strolled","marched"],"k":"B","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which revision combines sentences 3 and 4 to improve the flow?","o":["When my name was called, I walked onto the stage.","My name was called, walking onto the stage.","My name was called and then walked onto the big stage.","My name was called, I walked onto the stage."],"k":"A","sk":"Revises a sentence to make the meaning clearer","b":"191–200","g":"WR"}],"set":"3"},{"p":3,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which revision of sentence 6 is the MOST concise and formal?","o":["His methods were extremely important and super helpful to science.","His methods were very important, and they were important to science.","His methods really helped science a lot, which was very, very good.","His careful methods helped shape the scientific method."],"k":"D","sk":"Keeps a consistent formal style and objective tone","b":"191–200","g":"WR"}],"set":"4"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Which group of words is a dependent clause?","o":["after a long delay","in the early morning hours","because the train was late","the train was late"],"k":"C","sk":"Identifies phrases and clauses and their functions","b":"191–200","g":"GU"},{"n":2,"t":"mc","s":"Which sentence is a simple sentence?","o":["The students raised their hands, and the teacher smiled.","The students in the front row raised their hands.","The students raised their hands because they knew the answer.","When the teacher asked, the students raised their hands."],"k":"B","sk":"Forms simple, compound and complex sentences","b":"191–200","g":"GU"},{"n":3,"t":"mc","s":"Which of these is a fragment?","o":["We hoped to see the comet before sunrise.","Hoping to see the comet, we woke early.","We woke early because we hoped to see the comet.","Hoping to see the comet before sunrise."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"}],"set":"5"},{"p":4,"goal":"GU","items":[{"n":1,"t":"mc","s":"What is the BEST way to fix the comma splice in sentence 2?","o":["We saw ancient pottery, and we also saw a huge meteorite.","We saw, ancient pottery we also saw a huge meteorite.","We saw ancient pottery we also saw a huge meteorite.","We saw ancient pottery, we also, saw a huge meteorite."],"k":"A","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"},{"n":2,"t":"mc","s":"In sentence 1, what is the function of the phrase “in Riyadh”?","o":["It tells when the class visited.","It tells where the museum is.","It names who visited the museum.","It tells why the class visited."],"k":"B","sk":"Identifies phrases and clauses and their functions","b":"191–200","g":"GU"}],"set":"6"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Which word correctly completes the sentence?\n“The coach told Ali and ___ to practice more.”","o":["myself","me","I","mine"],"k":"B","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":2,"t":"mc","s":"Which word correctly completes the sentence?\n“The bell had already ___ when we arrived.”","o":["ringed","rings","rung","rang"],"k":"C","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"}],"set":"7"},{"p":5,"goal":"GU","items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 1?","o":["Every Friday, my aunt teaches my cousin and me how to cook.","Every Friday, my aunt teaches myself and my cousin how to cook.","Every Friday, my aunt teaches me and my cousin how to cooks.","Every Friday, my aunt teaches my cousin and myself how to cook."],"k":"A","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":2,"t":"mc","s":"Which words should replace “had gave” in sentence 5?","o":["had give","was gave","had given","has gave"],"k":"C","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"}],"set":"8"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which sentence uses commas correctly?","o":["It was, a cold windy morning.","It was a, cold windy morning.","It was a cold, windy morning.","It was a cold windy, morning."],"k":"C","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Which sentence uses commas correctly?","o":["Jeddah, which is on the Red Sea, has a busy port.","Jeddah which is on the Red Sea, has a busy port.","Jeddah, which is on the Red Sea has a busy port.","Jeddah which, is on the Red Sea has a busy port."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"}],"set":"9"},{"p":6,"goal":"ME","items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 2?","o":["Diriyah, which is on the edge of Riyadh was the first capital of the Saudi state.","Diriyah which is on the edge of Riyadh was, the first capital of the Saudi state.","Diriyah which, is on the edge of Riyadh, was the first capital of the Saudi state.","Diriyah, which is on the edge of Riyadh, was the first capital of the Saudi state."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Where should a comma be added in sentence 7?","o":["after “glowed”","after “set”","after “walls”","after “As”"],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"}],"set":"10"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which title is capitalized correctly?","o":["the Lion and the Mouse","The lion and the mouse","The Lion And The Mouse","The Lion and the Mouse"],"k":"D","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Which sentence is capitalized correctly?","o":["We tasted Turkish coffee and Moroccan mint tea.","We tasted Turkish Coffee and Moroccan Mint Tea.","We tasted turkish coffee and moroccan mint tea.","We tasted turkish coffee and Moroccan mint tea."],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":3,"t":"mc","s":"Which sentence uses an apostrophe correctly?","o":["Who’se going to clean the classroom?","Whose going to clean the classroom?","Who’s going to clean the classroom?","Whos going to clean the classroom?"],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"}],"set":"11"},{"p":7,"goal":"ME","items":[{"n":1,"t":"mc","s":"What is the correct way to write the end of sentence 1?","o":["at King Abdulaziz university.","at king Abdulaziz university.","at King abdulaziz University.","at King Abdulaziz University."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Which word is spelled correctly?","o":["temperture","temperature","temprature","tempreture"],"k":"B","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"}],"set":"12"}]},{"id":"R6","n":6,"title":"RIT 6","goal":"RIT","band":"201–210","skills":["Chooses a transition that connects ideas","Paraphrases or cites a source correctly","Recognizes complete sentences, fragments and run-ons","Chooses relevant evidence to support a point"],"vocab":[],"sets":[{"p":0,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which phrase in sentence 3 shows how it connects to sentence 2?","o":["early start times","many students","the sleep they need","Because of this shift"],"k":"D","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":2,"t":"mc","s":"Which piece of evidence would BEST support sentence 3?","o":["Alarm clocks were invented hundreds of years ago and are now included on most phones.","A national survey found that most teenagers sleep less than the eight to ten hours doctors recommend.","Many teenagers enjoy staying up late at night to watch movies or chat online with their friends on weekends.","Some schools in other countries begin their classes as late as nine o’clock in the morning."],"k":"B","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":3,"t":"mc","s":"Which source would be the MOST credible for evidence about teenagers’ sleep?","o":["a study published by a children’s hospital sleep center","a magazine article about celebrities’ daily routines","a video in which a student shares opinions about mornings","a website that sells mattresses and pillows for teens"],"k":"A","sk":"Chooses a useful source or research question","b":"201–210","g":"WR"}],"set":"1"},{"p":1,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which transition could replace “In addition” in sentence 5 without changing the meaning?","o":["Nevertheless","Consequently","Moreover","Instead"],"k":"C","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":2,"t":"mc","s":"Which sentence describes an effect of the falling water level?","o":["sentence 2","sentence 4","sentence 5","sentence 6"],"k":"D","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":3,"t":"mc","s":"Which heading would BEST fit a new section that begins with sentence 7?","o":["The History of Jordan","Possible Solutions","How to Float on Water","Why the Water Is Salty"],"k":"B","sk":"Chooses a topic sentence that introduces the main idea","b":"201–210","g":"WR"}],"set":"2"},{"p":2,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which sentence could be added after sentence 2 to show Reema’s feelings?","o":["The judges sat at a long table near the front of the hall.","The violin is a string instrument that is usually played with a long bow.","My fingers were so cold that I wondered if they would work at all.","The hall had been built about twenty years earlier by the city."],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":2,"t":"mc","s":"Which words in sentence 7 are redundant and could be removed?","o":["the final note","began to clap","for a moment","and quiet"],"k":"D","sk":"Revises to remove wordy or repeated language","b":"201–210","g":"WR"}],"set":"3"},{"p":3,"goal":"WR","items":[{"n":1,"t":"mc","s":"Sentence 4 copies the source word for word. Which revision is the BEST paraphrase?","o":["He argued that our eyes send out rays of light that bounce back from the objects.","He explained that vision happens when light bounces off an object and travels into the eye.","He argued that we see objects because light reflects off them and enters our eyes.","He believed that people cannot see anything at all unless the sun is shining very brightly above them."],"k":"B","sk":"Paraphrases or cites a source correctly","b":"201–210","g":"WR"},{"n":2,"t":"mc","s":"If Bassam keeps the exact words in sentence 4, what must he do?","o":["put them in quotation marks and credit Dr. Farouk","change one or two words so they are not exactly the same","move the sentence to the end of the report","write them in capital letters to show their importance"],"k":"A","sk":"Paraphrases or cites a source correctly","b":"201–210","g":"WR"},{"n":3,"t":"mc","s":"Which information from the source could Bassam add to sentence 1 to make it more precise?","o":["that he wrote in a library","that he had many brothers","that he was born around 965","that he lived in Cairo as a child"],"k":"C","sk":"Uses notes and facts accurately in writing","b":"201–210","g":"WR"}],"set":"4"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Which is the BEST way to combine the sentences to show cause and effect?\n“The bridge was closed. Traffic was heavy downtown.”","o":["Because the bridge was closed, traffic was heavy downtown.","Although the bridge was closed, traffic was heavy downtown.","The bridge was closed, but traffic was heavy downtown.","The bridge was closed, or traffic was heavy downtown."],"k":"A","sk":"Combines sentences correctly","b":"201–210","g":"GU"}],"set":"5"},{"p":4,"goal":"GU","items":[{"n":1,"t":"mc","s":"Sentence 3 is a fragment. Which revision fixes it correctly?","o":["We also saw a huge meteorite which, fell in the Empty Quarter long ago.","We also saw a huge meteorite, it fell in the Empty Quarter, long ago.","We also saw a huge meteorite, which fell in the Empty Quarter long ago.","We also saw a huge meteorite. Which fell in the Empty Quarter long ago."],"k":"C","sk":"Recognizes complete sentences, fragments and run-ons","b":"201–210","g":"GU"},{"n":2,"t":"mc","s":"What is the BEST way to combine sentences 4 and 5?","o":["Our guide explained how scientists study objects, to find out how old they are.","Our guide explained, how scientists study objects to find out how old they are.","Our guide explained how scientists study objects; to find out how old they are.","Our guide explained how scientists study objects to find out how old they are."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"201–210","g":"GU"},{"n":3,"t":"mc","s":"Which sentence about the trip is a complex sentence?","o":["We left the museum and then ate lunch in the big park.","We left the museum, and then we ate lunch.","After we left the museum, we ate lunch in the park.","We ate lunch in the park near the museum."],"k":"C","sk":"Forms simple, compound and complex sentences","b":"201–210","g":"GU"}],"set":"6"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Which sentence has a misplaced modifier?","o":["The man walked his dog in a raincoat.","The man in a raincoat walked his dog.","Wearing a raincoat, the man walked his dog.","The man walked his dog while wearing a raincoat."],"k":"A","sk":"Places modifiers correctly","b":"201–210","g":"GU"},{"n":2,"t":"mc","s":"Which sentence uses verb tenses correctly?","o":["I read when the phone was ringing then.","I was reading when the phone rings.","I am reading when the phone rang.","I was reading when the phone rang."],"k":"D","sk":"Uses verb tenses correctly","b":"201–210","g":"GU"}],"set":"7"},{"p":5,"goal":"GU","items":[{"n":1,"t":"mc","s":"In sentence 2, what does the phrase “a rice dish with chicken and spices” do?","o":["It shows where the family ate dinner.","It names the person who made the dish.","It tells when the cooking lesson took place.","It explains what kabsa is."],"k":"D","sk":"Identifies phrases and clauses and their functions","b":"201–210","g":"GU"},{"n":2,"t":"mc","s":"Which sentence is written correctly?","o":["Me and my cousin were proud of ourself.","My cousin and I were proud of ourselves.","My cousin and me were proud of ourselves.","My cousin and I was proud of ourselves."],"k":"B","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":3,"t":"mc","s":"Which words correctly complete the sentence?\n“By the time dinner was ready, we ___ the table.”","o":["had setted","had sat","had set","have set"],"k":"C","sk":"Uses perfect verb tenses","b":"201–210","g":"GU"}],"set":"8"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which sentence uses a comma correctly?","o":["Exhausted from the long, hike we rested by the stream.","Exhausted from the long hike we rested, by the stream.","Exhausted, from the long hike we rested by the stream.","Exhausted from the long hike, we rested by the stream."],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"201–210","g":"ME"},{"n":2,"t":"mc","s":"Which sentence has an unnecessary comma?","o":["After dinner, my brother went to the game.","My brother and his friend, went to the game.","My brother and his friend went to the game.","My brother went to the game, and his friend went too."],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"201–210","g":"ME"}],"set":"9"},{"p":6,"goal":"ME","items":[{"n":1,"t":"mc","s":"Where should a comma be added in sentence 3?","o":["after “narrow”","after “mud-brick”","after “streets”","after “walked”"],"k":"A","sk":"Uses commas between coordinate adjectives","b":"201–210","g":"ME"},{"n":2,"t":"mc","s":"What is the correct way to begin sentence 4?","o":["The At-Turaif district a UNESCO World Heritage Site","The At-Turaif, district a UNESCO World Heritage Site,","The At-Turaif district, a UNESCO World Heritage Site,","The At-Turaif district, a UNESCO World Heritage Site"],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"}],"set":"10"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which word correctly completes the sentence?\n“The school ___ announced a new reading program.”","o":["principle","principal","principel","princible"],"k":"B","sk":"Spells grade-level words correctly","b":"201–210","g":"ME"}],"set":"11"},{"p":7,"goal":"ME","items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 2?","o":["I asked her, “What made you want to study the ocean?”","I asked her, “what made you want to study the ocean?”","I asked her “What made you want to study the ocean.”","I asked her, “What made you want to study the ocean”?"],"k":"A","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":2,"t":"mc","s":"How should “Al-Qahtanis” be written in sentence 4?","o":["Al-Qahtanis’","Al-Qahtanis","Al-Qahtani’s","Al-Qahtani’s’"],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":3,"t":"mc","s":"How should the article title Saving Our Reefs in sentence 6 be written?","o":["in italics","in all capital letters","in parentheses","in quotation marks"],"k":"D","sk":"Capitalizes and punctuates titles of works","b":"201–210","g":"ME"}],"set":"12"}]},{"id":"R7","n":7,"title":"RIT 7","goal":"RIT","band":"211–220","skills":["Forms simple, compound and complex sentences","Places modifiers correctly","Uses commas between coordinate adjectives","Uses commas, parentheses or dashes to set off extra information"],"vocab":[],"sets":[{"p":1,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which revision of sentence 2 uses the MOST precise language?","o":["Its water is nearly ten times saltier than ocean water, so swimmers float easily.","Its water has a lot of salt in it, which is the main reason people can float there.","Its water is very, very salty, so people can float on top of it super easily.","Its water is salty like other seas and oceans, so people float on it."],"k":"A","sk":"Chooses precise or vivid language","b":"211–220","g":"WR"}],"set":"1"},{"p":2,"goal":"WR","items":[{"n":1,"t":"mc","s":"Why does the writer use short sentences in 3, 4 and 5?","o":["to show that time seems to move in quick, tense steps","to describe the history of the music hall","to show that the narrator feels bored and calm","to explain exactly how a violin produces its beautiful sound"],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"211–220","g":"WR"},{"n":2,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["My teacher has taught violin lessons for more than ten years.","Violins have four strings, which are tuned to different notes.","I bowed, and for the first time all day, my hands stopped shaking.","The audition was held in the city’s largest music hall that year."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}],"set":"2"},{"p":3,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which detail is NOT needed when Bassam cites this source?","o":["the title of the book","the color of the book’s cover","the year that the book was first published","the name of the author"],"k":"B","sk":"Paraphrases or cites a source correctly","b":"211–220","g":"WR"},{"n":2,"t":"mc","s":"Bassam wants to add a sentence about the camera obscura, which this source does not mention. What should he do?","o":["say that Dr. Farouk wrote about it too","copy the information from a friend’s report","make up details that sound scientific","find another credible source and credit it"],"k":"D","sk":"Chooses a useful source or research question","b":"211–220","g":"WR"},{"n":3,"t":"mc","s":"Which sentence would be the BEST introduction to the report?","o":["A thousand years ago, a scientist in Basra asked a simple question: how do we see?","I read a book about scientists, and Ibn al-Haytham was in that book I read.","This report is about Ibn al-Haytham, and it will tell you some things about him.","Science is a subject that many people study in schools and universities all over the world."],"k":"A","sk":"Chooses an effective introduction","b":"211–220","g":"WR"}],"set":"3"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Which sentence is a compound-complex sentence?","o":["When the storm ended, we went outside, and the children played in the puddles.","We went outside to play in the cool air after the storm ended late last night.","When the long storm finally ended that evening, we all went outside to play in the yard.","The storm ended, and we went outside to play in the big puddles near the garden."],"k":"A","sk":"Forms simple, compound and complex sentences","b":"211–220","g":"GU"},{"n":2,"t":"mc","s":"In the sentence “The girl with the red backpack is my sister,” what does the phrase “with the red backpack” do?","o":["It names the subject of the sentence.","It describes the verb “is.”","It describes the noun “girl.”","It shows when the action happens."],"k":"C","sk":"Identifies phrases and clauses and their functions","b":"211–220","g":"GU"}],"set":"4"},{"p":4,"goal":"GU","items":[{"n":1,"t":"mc","s":"What kind of sentence is sentence 6?","o":["complex","compound-complex","simple","compound"],"k":"A","sk":"Forms simple, compound and complex sentences","b":"211–220","g":"GU"},{"n":2,"t":"mc","s":"Which revision of sentence 7 joins two independent clauses with a coordinating conjunction?","o":["The trip taught me that history is all around us every single day.","Because the trip was fun, it taught me that history is all around us.","The fun trip to the museum taught me that history is all around us.","The trip was fun, and it taught me that history is all around us."],"k":"D","sk":"Forms simple, compound and complex sentences","b":"211–220","g":"GU"}],"set":"5"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Which sentence has a dangling modifier?","o":["Running for the bus, I dropped my backpack.","Running for the bus, my backpack fell open.","As I ran for the bus, my backpack fell open.","My backpack fell open as I ran for the bus."],"k":"B","sk":"Places modifiers correctly","b":"211–220","g":"GU"}],"set":"6"},{"p":5,"goal":"GU","items":[{"n":1,"t":"mc","s":"Sentence 3 has a dangling modifier. Which revision is correct?","o":["Tears filled my eyes, chopping the onions.","Chopping the onions, tears were filling my eyes.","Chopping the onions, my eyes filled with tears.","As I chopped the onions, tears filled my eyes."],"k":"D","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":2,"t":"mc","s":"Sentence 4 has a misplaced modifier. Which revision is correct?","o":["With a smile, my aunt showed us how to measure the spices carefully.","My aunt showed us how to measure the spices with a smile carefully.","My aunt showed us how to measure the spices carefully with a smile.","My aunt showed us with a smile how to measure the carefully spices."],"k":"A","sk":"Places modifiers correctly","b":"211–220","g":"GU"}],"set":"7"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which sentence is punctuated correctly?","o":["She bought three, small wooden boxes.","She bought three small wooden boxes.","She bought three, small, wooden boxes.","She bought three small, wooden boxes."],"k":"B","sk":"Uses commas between coordinate adjectives","b":"211–220","g":"ME"},{"n":2,"t":"mc","s":"Which sentence is punctuated correctly?","o":["The book, that I borrowed is overdue.","The book, that I borrowed, is overdue.","The book that I borrowed is overdue.","The book that I borrowed, is overdue."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"}],"set":"8"},{"p":6,"goal":"ME","items":[{"n":1,"t":"mc","s":"Why are there commas around “who grew up nearby” in sentence 5?","o":["The clause states the main idea of the sentence, so it must be set apart from it.","Commas must always come both before and after the word “who” in every sentence.","The clause is needed to tell readers exactly which guide the writer is talking about.","The clause adds extra information that is not needed to identify the guide."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":2,"t":"mc","s":"In sentence 7, why is there a comma between “warm” and “golden”?","o":["A comma is needed before the last noun in every sentence.","The word “golden” begins a new independent clause.","They are coordinate adjectives that each describe the color.","A comma always separates a color word from any other adjective."],"k":"C","sk":"Uses commas between coordinate adjectives","b":"211–220","g":"ME"}],"set":"9"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which word is spelled correctly?","o":["consciense","conscience","concience","conshience"],"k":"B","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"}],"set":"10"},{"p":7,"goal":"ME","items":[{"n":1,"t":"mc","s":"In sentence 3, why are single quotation marks used around the father’s words?","o":["They show that the father was speaking quietly.","They show a quotation inside another quotation.","They show that the words are a title of a book.","They show that the words are not important."],"k":"B","sk":"Punctuates dialogue and quotations","b":"211–220","g":"ME"},{"n":2,"t":"mc","s":"Why is a colon used in sentence 7?","o":["to join two words into a compound word","to show that the sentence is a question","to introduce the advice that follows","to separate the hours and minutes of a time"],"k":"C","sk":"Uses semicolons and colons correctly","b":"211–220","g":"ME"}],"set":"11"}]},{"id":"R8","n":8,"title":"RIT 8","goal":"RIT","band":"221–230","skills":["Puts sentences or events in a logical order","Chooses an effective concluding sentence","Places modifiers correctly","Uses commas, parentheses or dashes to set off extra information"],"vocab":[],"sets":[{"p":0,"goal":"WR","items":[{"n":1,"t":"mc","s":"How could Abdulaziz BEST improve the organization of his essay?","o":["Move sentence 7 to the very beginning so that the essay starts with its conclusion.","Combine sentences 2 and 6 because they are both about school sports.","Move sentence 4 to follow sentence 1 so that the claim comes before the reasons.","Remove sentence 5 so that readers do not learn about any of the opposing views at all."],"k":"C","sk":"Puts sentences or events in a logical order","b":"221–230","g":"WR"}],"set":"1"},{"p":1,"goal":"WR","items":[{"n":1,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["Farming is an important part of life in many countries in the Middle East today.","The Red Sea is famous for its colorful coral reefs and for its many kinds of tropical fish.","Unless people find a way to balance their water needs, the Dead Sea may keep shrinking.","Floating in the Dead Sea is a popular activity for tourists from around the world."],"k":"C","sk":"Chooses an effective concluding sentence","b":"221–230","g":"WR"}],"set":"2"},{"p":null,"goal":"GU","items":[{"n":1,"t":"mc","s":"Salma ate nearly all of the pizza. Which sentence says this clearly?","o":["Almost Salma ate the whole pizza.","Salma ate the whole almost pizza.","Salma ate the whole pizza almost.","Salma ate almost the whole pizza."],"k":"D","sk":"Places modifiers correctly","b":"221–230","g":"GU"}],"set":"3"},{"p":6,"goal":"ME","items":[{"n":1,"t":"mc","s":"What is the correct way to write sentence 6?","o":["The people who built, these houses used clay, straw and palm wood.","The people who built these houses used clay, straw and palm wood.","The people, who built these houses used clay, straw and palm wood.","The people who built these houses, used clay, straw and palm wood."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"221–230","g":"ME"}],"set":"4"},{"p":null,"goal":"ME","items":[{"n":1,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Ali said, “My teacher told us, ‘Always check your work.’”","Ali said “My teacher told us, ‘Always check your work.’”","Ali said, “My teacher told us, Always check your work.”","Ali said, “My teacher told us, “Always check your work.””"],"k":"A","sk":"Punctuates dialogue and quotations","b":"221–230","g":"ME"}],"set":"5"}]}],"mocks":[{"id":"A","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"The Great Green Wall","genre":"draft","paras":["(1) The Sahara Desert is slowly spreading south into the Sahel a dry region of Africa. (2) As the land turns to desert, farmers lose the soil they need to grow food. (3) In 2007, African countries launched a bold plan called the Great Green Wall. (4) The goal is to grow a belt of trees and plants about 8,000 kilometers long across the continent. (5) Planting trees, the soil is protected from wind. (6) Communities also earn money by selling fruit, gum and other products from the plants. (7) The project faces challenges, including drought and a lack of funding."],"intro":"Hadeel is writing a report about an environmental project. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to write the end of sentence 1?","o":["into the Sahel a dry region, of Africa.","into the Sahel a dry, region of Africa.","into the Sahel, a dry region of Africa.","into the, Sahel a dry region of Africa."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Which transition BEST begins sentence 3 to show a response to the problem?","o":["In much the same way,","For example,","On the other hand,","To fight this problem,"],"k":"D","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Which sentence BEST states the main idea of the report?","o":["The Sahel is located just south of the Sahara Desert in Africa.","The Great Green Wall is a large project to stop the desert from spreading.","Farmers in many parts of Africa grow crops such as millet and sorghum.","Trees provide shade, fruit and safe homes for many different kinds of birds and insects."],"k":"B","sk":"Chooses a topic sentence that introduces the main idea","b":"191–200","g":"WR"},{"n":4,"t":"mc","s":"Which sentence would BEST follow sentence 7 to conclude the report?","o":["Even so, each new tree brings the Sahel a step closer to a greener future.","Drought happens when an area receives much less rain than usual for a long time.","The Sahara is the largest hot desert in the world, covering much of North Africa.","Gum arabic is used in many foods, drinks and medicines around the world."],"k":"A","sk":"Chooses an effective concluding sentence","b":"191–200","g":"WR"},{"n":5,"t":"mc","s":"Which revision of sentence 5 corrects the dangling modifier?","o":["The soil, planting trees, is protected from wind.","Planting trees, the strong wind is kept away from the dry soil.","Planting trees, the soil is protected from the wind.","By planting trees, communities protect the soil from wind."],"k":"D","sk":"Places modifiers correctly","b":"201–210","g":"GU"},{"n":6,"t":"mc","s":"Which detail would BEST support sentence 7?","o":["The Sahel stretches from Senegal in the west to Djibouti in the east.","Some countries have planted only a small part of their share because of limited money.","Many of the trees that have been planted are acacias, which grow well in dry, sandy soil.","Some farmers in the Sahel raise goats, camels and cattle for milk."],"k":"B","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"}]},{"passage":{"title":"The Science Competition","genre":"draft","paras":["(1) Our team had spent three months building a water filter from sand gravel and charcoal. (2) On the morning of the competition, we set it up carefully on our table. (3) When the judges arrived, I poured a cup of muddy water into the top. (4) Nothing came out. (5) My teammate Sami and me looked at each other with wide eyes. (6) Then, drop by drop, clear water began to fall into the glass. (7) The judges smiled at each other, and one of them wrote something on her clipboard."],"intro":"Faisal wrote a story. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Where should a comma be added in sentence 1?","o":["after “sand”","after “filter”","after “building”","after “months”"],"k":"A","sk":"Uses commas in a series","b":"191–200","g":"ME"},{"n":8,"t":"mc","s":"Which words should replace “Sami and me” in sentence 5?","o":["Sami and myself","me and Sami","Sami and I","Sami and mine"],"k":"C","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":9,"t":"mc","s":"What is the effect of the short sentence 4?","o":["It describes the setting of the competition.","It creates a moment of suspense and worry.","It shows that the judges are pleased.","It explains how a water filter works."],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":10,"t":"mc","s":"Which phrase in sentence 6 slows the pace to show the moment clearly?","o":["drop by drop","clear water","Then","into the glass"],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":11,"t":"mc","s":"Which sentence could be added after sentence 3 to show Faisal’s feelings?","o":["Muddy water contains tiny pieces of soil that make it look brown.","Charcoal is made by heating wood slowly until it turns black and brittle.","The competition was held in the gym of a large school downtown.","My hands shook so much that some of the water splashed onto the table."],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["Our school has a science club that meets every Monday after classes.","Sami lives near the school, so he usually walks there in the mornings.","Whatever the results, I knew that our three months of work had been worth it.","Water filters are used in many homes to remove dirt and germs from drinking water."],"k":"C","sk":"Chooses an effective concluding sentence","b":"201–210","g":"WR"}]},{"passage":{"title":"Should Cursive Still Be Taught?","genre":"draft","paras":["(1) In an age of keyboards and touch screens some people believe cursive handwriting is no longer useful. (2) However, schools should continue to teach it. (3) Research suggests that writing by hand helps students remember information better than typing. (4) Cursive also allows students to read historical documents, letters and diaries. (5) Critics say that the time spent on cursive could be used for typing lessons. (6) But students can learn both skills; cursive lessons take only a few minutes a day. (7) Teaching cursive helps students to think clearly, read history and expressing themselves."],"intro":"Huda wrote an argument essay. Read her draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states Huda’s claim?","o":["sentence 1","sentence 2","sentence 3","sentence 5"],"k":"B","sk":"States a clear claim or thesis","b":"191–200","g":"WR"},{"n":14,"t":"mc","s":"Where should a comma be added in sentence 1?","o":["after “keyboards”","after “believe”","after “age”","after “screens”"],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":15,"t":"mc","s":"Which word should replace “expressing” in sentence 7?","o":["express","expressed","expresses","to expressing"],"k":"A","sk":"Uses parallel structure","b":"191–200","g":"GU"},{"n":16,"t":"mc","s":"What is the purpose of sentence 6?","o":["to agree that typing is more important","to describe how cursive letters are formed","to answer the counterclaim in sentence 5","to introduce the writer’s first reason"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"191–200","g":"WR"},{"n":17,"t":"mc","s":"Which transition could replace “But” in sentence 6, keeping the same meaning but sounding more formal?","o":["In addition,","Plus,","So,","Nevertheless,"],"k":"D","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":18,"t":"mc","s":"Which source would provide the MOST credible support for sentence 3?","o":["a study published in a journal of educational psychology","a cartoon about a friendly robot that learns to write by hand","a post from a student who enjoys writing in cursive","an online store that sells fancy pens and notebooks"],"k":"A","sk":"Chooses a useful source or research question","b":"201–210","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence is the MOST concise?","o":["The decision that was decided at the end will be announced on the day of Monday.","On Monday, the decision that is final will be announced and made known on Monday.","The final decision will be announced on Monday.","The final decision, which is the last decision, will be announced on Monday."],"k":"C","sk":"Revises to remove wordy or repeated language","b":"191–200","g":"WR"},{"n":20,"t":"mc","s":"Which sentence would BEST introduce a paragraph that classifies types of clouds?","o":["Rain falls from clouds when water droplets become too heavy to float.","Clouds can be grouped into three main types based on their shape and height.","I really like to look up at the clouds when I lie on the soft grass in the park.","Clouds are white or gray, and they float high above us in the sky."],"k":"B","sk":"Chooses a topic sentence that introduces the main idea","b":"191–200","g":"WR"},{"n":21,"t":"mc","s":"Read the quotation from a source.\n“Honey found in ancient Egyptian tombs was still safe to eat after thousands of years.”\nWhich sentence uses the quotation correctly?","o":["Dr. Sami Nour, food historian, Honey found in ancient Egyptian tombs was still safe to eat after thousands of years.","Food historian Dr. Sami Nour writes, “Honey found in ancient Egyptian tombs was still safe to eat after thousands of years.”","Honey found in ancient Egyptian tombs was still safe to eat after thousands of years, which is something I discovered on my own.","“Honey found in ancient Egyptian tombs was still safe to eat after thousands of years” and that is interesting."],"k":"B","sk":"Paraphrases or cites a source correctly","b":"201–210","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which group of words is a prepositional phrase?","o":["under the old bridge","the bridge collapsed","because it was raining","when we arrived"],"k":"A","sk":"Identifies phrases and clauses and their functions","b":"191–200","g":"GU"},{"n":23,"t":"mc","s":"Which sentence is a compound sentence?","o":["When the lights went out, we lit candles.","Lighting candles, we waited in the dark.","We lit candles after the lights went out.","The lights went out, so we lit candles."],"k":"D","sk":"Forms simple, compound and complex sentences","b":"191–200","g":"GU"},{"n":24,"t":"mc","s":"Which word correctly completes the sentence?\n“The flock of birds ___ south every winter.”","o":["are flying","fly","flies","have flown"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which words correctly complete the sentence?\n“She has ___ her bicycle to school every day this week.”","o":["rided","ride","rode","ridden"],"k":"D","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which sentence has a misplaced modifier?","o":["A lizard with a long tail crossed my path to school.","I saw a lizard on the way to school with a long tail.","On the way to school, I saw a lizard with a long tail.","I saw a lizard with a long tail on the way to school."],"k":"B","sk":"Places modifiers correctly","b":"191–200","g":"GU"},{"n":27,"t":"mc","s":"Which sentence uses pronouns correctly?","o":["The prize was shared by Laila and me.","The prize was shared by Laila and I.","The prize was shared by Laila and myself.","The prize was shared by I and Laila."],"k":"A","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":28,"t":"mc","s":"Which sentence is a complex sentence?","o":["Most students finished the long test early.","The test was very long, but most students finished it early.","Although the test was long, most students finished early.","The test was long; most students finished early."],"k":"C","sk":"Forms simple, compound and complex sentences","b":"191–200","g":"GU"},{"n":29,"t":"mc","s":"Which sentence uses parallel structure?","o":["The museum offers tours, workshops and giving lectures.","The museum offers tours, workshops and lectures.","The museum offers touring, workshops and to lecture.","The museum offers tours, to work in shops and lectures."],"k":"B","sk":"Uses parallel structure","b":"191–200","g":"GU"},{"n":30,"t":"mc","s":"Which sentence has a dangling modifier?","o":["The water tasted wonderful after I finished the race.","After I finished the race, the water tasted wonderful.","After finishing the race, I drank some cold water.","After finishing the race, the water tasted wonderful."],"k":"D","sk":"Places modifiers correctly","b":"201–210","g":"GU"},{"n":31,"t":"mc","s":"Which word correctly completes the sentence?\n“Neither the teacher nor the students ___ the answer.”","o":["has known","is knowing","know","knows"],"k":"C","sk":"Uses correlative conjunctions","b":"201–210","g":"GU"},{"n":32,"t":"mc","s":"Which sentence uses verb tenses correctly?","o":["By the time we reached the station, the train had left.","By the time we reach the station, the train had left.","By the time we reached the station, the train has left.","By the time we reached the station, the train leaves."],"k":"A","sk":"Uses perfect verb tenses","b":"201–210","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses commas correctly?","o":["We hiked up the, steep rocky trail.","We hiked up the steep rocky, trail.","We hiked, up the steep rocky trail.","We hiked up the steep, rocky trail."],"k":"D","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["My uncle speaks English, French and Arabic.","My Uncle speaks English, French and Arabic.","My uncle speaks english, french and arabic.","My uncle speaks English, french and Arabic."],"k":"A","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["Mount Uhud which, is near Medina is an important historical site.","Mount Uhud, which is near Medina, is an important historical site.","Mount Uhud which is near Medina, is an important historical site.","Mount Uhud, which is near Medina is an important historical site."],"k":"B","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses an apostrophe correctly?","o":["The bus driver’s jacket was hanging on the seat’s.","The bus drivers’s jacket was hanging on the seat.","The bus driver’s jacket was hanging on the seat.","The bus drivers jacket was hanging on the seat."],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“I can’t believe it,” said Maha. “We actually won!”","“I can’t believe it,” said Maha. “we actually won!”","“I can’t believe it” said Maha. “We actually won!”","“I can’t believe it,” said Maha “we actually won!”"],"k":"A","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which title is capitalized correctly?","o":["The secret of the old lighthouse","The Secret of the Old Lighthouse","The Secret Of The Old Lighthouse","the Secret of the Old Lighthouse"],"k":"B","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses a colon correctly?","o":["Bring: three things to class a pencil, a notebook and a ruler.","Bring three things to class a pencil: a notebook and a ruler.","Bring three things: to class a pencil, a notebook and a ruler.","Bring three things to class: a pencil, a notebook and a ruler."],"k":"D","sk":"Uses semicolons and colons correctly","b":"191–200","g":"ME"},{"n":40,"t":"mc","s":"Which word is spelled correctly?","o":["acheivement","achievment","achievement","acheevement"],"k":"C","sk":"Spells grade-level words correctly","b":"191–200","g":"ME"},{"n":41,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Students who finish early, may read quietly.","Students, who finish early may read quietly.","Students who finish early may read quietly.","Students, who finish early, may read quietly."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":42,"t":"mc","s":"Which sentence uses commas correctly?","o":["After the long exciting game the players, celebrated.","After, the long exciting game the players celebrated.","After the long, exciting, game the players celebrated.","After the long, exciting game, the players celebrated."],"k":"D","sk":"Uses a comma after an introductory word, phrase or clause","b":"201–210","g":"ME"},{"n":43,"t":"mc","s":"Which sentence uses a hyphen correctly?","o":["My brother is a well known-artist.","My brother is a well-known artist.","My brother is a well known artist-.","My brother is a-well known artist."],"k":"B","sk":"Uses hyphens and dashes correctly","b":"201–210","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"B","note":"Full practice test · 43 questions","sections":[{"passage":{"title":"How Bats Use Echolocation","genre":"draft","paras":["(1) Bats hunt at night, yet they rarely crash into anything. (2) Their secret is a skill called echolocation. (3) A bat makes high pitched sounds that most humans cannot hear. (4) When the sounds hits an object, they bounce back to the bat’s ears. (5) By listening to these echoes, a bat can tell how far away an object is, how big it is and even which way it is moving. (6) Some bats can detect an object as thin as a human hair. (7) Scientists have studied echolocation to design better tools for people who are blind."],"intro":"Raghad is writing a science report. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word in sentence 1 signals a contrast?","o":["rarely","anything","hunt","yet"],"k":"D","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":2,"t":"mc","s":"Which domain-specific word does Raghad explain for her readers?","o":["echolocation","object","design","secret"],"k":"A","sk":"Chooses precise or vivid language","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Which word should replace “hits” in sentence 4?","o":["has hit","hit","is hitting","hitting"],"k":"B","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":4,"t":"mc","s":"What is the correct way to write “high pitched” in sentence 3?","o":["high pitched-","highpitched","high-pitched","high-pitch-ed"],"k":"C","sk":"Uses hyphens and dashes correctly","b":"201–210","g":"ME"},{"n":5,"t":"mc","s":"Which sentence would BEST follow sentence 6?","o":["Some people are afraid of bats because of scary stories and movies.","This ability helps bats catch tiny insects, even in complete darkness.","Human hair grows about one centimeter every month on most people.","Bats are the only mammals that are truly able to fly through the air."],"k":"B","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["Sound travels through air as waves, and it can also travel through water and solid objects.","Bats sleep during the day, usually hanging upside down in dark caves, hollow trees or old empty buildings.","From catching insects to inspiring new inventions, echolocation shows how much we can learn from nature.","Many kinds of animals are active at night, including owls, foxes and some kinds of snakes."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"The Broken Bridge","genre":"draft","paras":["(1) We had been hiking for two hours when we reached the stream. (2) The wooden bridge that crossed it was broken in the middle. (3) My friend Majed looked at the map, frowned and said, “There is no other way across.” (4) The water was cold, fast and deep. (5) Then Majed and me noticed a fallen tree a little farther down the bank. (6) Carefully, we crawled across the slippery trunk, one at a time. (7) When we reached the other side, Majed laughed and said “That was the best part of the trip!”"],"intro":"Saud wrote a story about a hiking trip. Read his draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which words should replace “Majed and me” in sentence 5?","o":["Majed and I","Majed and mine","Majed and myself","me and Majed"],"k":"A","sk":"Uses the correct pronoun case","b":"191–200","g":"GU"},{"n":8,"t":"mc","s":"Which transition could replace “Then” in sentence 5 to show a sudden turning point?","o":["In addition,","As a result,","For example,","Just then,"],"k":"D","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":9,"t":"mc","s":"Where should a comma be added in sentence 7?","o":["after “Majed”","after “laughed”","after “said”","after “best”"],"k":"C","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":10,"t":"mc","s":"What is the purpose of sentence 4?","o":["to show that the boys are tired from hiking","to show why the boys cannot simply wade across","to explain how the wooden bridge was built","to describe the weather on the day of the hike"],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":11,"t":"mc","s":"Which sentence could be added after sentence 6 to build suspense?","o":["Halfway across, the trunk creaked and shifted under my knees.","The map showed three trails that led to the top of the hill.","Trees can live for hundreds of years if they have enough water.","Majed has been my friend since we were in the first grade."],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"211–220","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the story?","o":["The stream flows into a small lake where many families like to have picnics on weekends.","Hiking boots should fit well and have strong soles that grip rocks, mud and wet trails.","Wooden bridges must be checked and repaired very often because heavy rain and wind can weaken them.","As we hiked on, I realized that the broken bridge had turned an ordinary hike into an adventure."],"k":"D","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"Should Students Learn About Money?","genre":"draft","paras":["(1) Every school should offer a course in personal finance. (2) Many young adults leave school without knowing how to make a budget, save money or avoid debt. (3) A finance course would teaches these skills before students need them. (4) Some people argue that parents, not schools, should teach children about money. (5) However, not all parents have the knowledge or time to teach these lessons, some never learned them themselves. (6) A school course would give every student the same opportunity. (7) In the end, learning to manage money is as important as learning math or science."],"intro":"Abeer wrote an argument essay. Read her draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states Abeer’s claim?","o":["sentence 1","sentence 2","sentence 4","sentence 6"],"k":"A","sk":"States a clear claim or thesis","b":"191–200","g":"WR"},{"n":14,"t":"mc","s":"Which word should replace “teaches” in sentence 3?","o":["teaching","taught","to teach","teach"],"k":"D","sk":"Uses modal auxiliaries","b":"191–200","g":"GU"},{"n":15,"t":"mc","s":"Which sentence presents a counterclaim?","o":["sentence 3","sentence 4","sentence 5","sentence 6"],"k":"B","sk":"Acknowledges and answers an opposing claim","b":"201–210","g":"WR"},{"n":16,"t":"mc","s":"Which transition could BEST begin sentence 6 to show how it connects to sentence 5?","o":["For example,","At the same time,","For this reason,","In contrast,"],"k":"C","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":17,"t":"mc","s":"What is the correct way to write the end of sentence 5?","o":["these lessons some never learned them themselves.","these lessons; some never learned them themselves.","these lessons: and some never learned them themselves.","these lessons, some, never learned them themselves."],"k":"B","sk":"Uses semicolons and colons correctly","b":"211–220","g":"ME"},{"n":18,"t":"mc","s":"Which evidence would BEST support sentence 2?","o":["Money has been used for thousands of years, starting with coins made of gold and silver.","Many young adults really enjoy shopping online for clothes, video games and electronics, especially on the weekends.","A national survey found that fewer than half of young adults could answer basic questions about saving and interest.","Banks are open on most weekdays, and some of them are also open on Saturday mornings."],"k":"C","sk":"Chooses relevant evidence to support a point","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence would BEST begin a compare-and-contrast essay about tablets and printed books?","o":["Many people read books and tablets, and some people do not read very much at all.","Tablets are electronic devices that use batteries, and books are made out of paper that comes from trees.","I like reading on my tablet, but my grandfather likes reading books better than tablets.","Tablets and printed books both deliver stories, but they offer very different reading experiences."],"k":"D","sk":"Chooses an effective introduction","b":"201–210","g":"WR"},{"n":20,"t":"mc","s":"A student writes, “The new playground is good.” Which revision is the MOST precise?","o":["The new playground has shaded benches, a climbing wall and a soft rubber floor.","The new playground is great, awesome and good in every way.","The new playground is good, and it is also very good for all of the kids at our school.","The new playground is really, really good and nice for everyone who goes there to play."],"k":"A","sk":"Chooses precise or vivid language","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Which question would BEST guide research about the effects of noise pollution on wildlife?","o":["Which city in the world has the most cars and trucks on its roads today?","What is the loudest sound that has ever been recorded anywhere on Earth?","Why do some people enjoy listening to loud music when they exercise?","How does traffic noise affect the behavior of birds that live in cities?"],"k":"D","sk":"Chooses a useful source or research question","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which sentence is a complex sentence?","o":["It might rain, but the game will start at five.","Unless it rains, the game will start at five.","The game will start at five in the evening.","The game will start at five; it might rain."],"k":"B","sk":"Forms simple, compound and complex sentences","b":"191–200","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“My grandmother has ___ letters to me every month.”","o":["writed","writ","written","wrote"],"k":"C","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"},{"n":24,"t":"mc","s":"Which word correctly completes the sentence?\n“The members of the club ___ planning a trip.”","o":["are","has been","was","is"],"k":"A","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which is the BEST way to fix the run-on sentence?\n“The library closes at six we should hurry.”","o":["The library closes, at six we should hurry.","The library closes at six, we should hurry.","The library closes at six, so we should hurry.","The library closes at six we, should hurry."],"k":"C","sk":"Recognizes complete sentences, fragments and run-ons","b":"191–200","g":"GU"},{"n":26,"t":"mc","s":"Which sentence has a misplaced modifier?","o":["The waiter served a sandwich to the man on a plate.","The man was served a sandwich on a plate.","On a plate, the waiter served the man a sandwich.","The waiter served the man a sandwich on a plate."],"k":"A","sk":"Places modifiers correctly","b":"201–210","g":"GU"},{"n":27,"t":"mc","s":"Which sentence uses parallel structure?","o":["Our goals are to read more, exercise daily and sleeping well.","Our goals are to read more, to exercise daily and to sleep well.","Our goals are to read more, exercising daily and to sleep well.","Our goals are reading more, to exercise daily and sleeping well."],"k":"B","sk":"Uses parallel structure","b":"201–210","g":"GU"},{"n":28,"t":"mc","s":"Which word correctly completes the sentence?\n“Mathematics ___ my favorite subject.”","o":["were","have been","are","is"],"k":"D","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which pronoun correctly completes the sentence in formal writing?\n“The winners of the contest were Talal and ___.”","o":["I","myself","mine","me"],"k":"A","sk":"Uses the correct pronoun case","b":"211–220","g":"GU"},{"n":30,"t":"mc","s":"What is the function of the dependent clause in this sentence?\n“The house that we visited was built in 1920.”","o":["It describes the verb “visited.”","It describes the noun “house.”","It tells when the house was built.","It acts as the subject of the sentence."],"k":"B","sk":"Identifies phrases and clauses and their functions","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which sentence has a dangling modifier?","o":["We saw the school as we turned the corner.","As we turned the corner, the school came into view.","Turning the corner, we saw the school.","Turning the corner, the school came into view."],"k":"D","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which words correctly complete the sentence?\n“By the time the movie ends, we ___ for three hours.”","o":["had been sitting","have been sitting","will have been sitting","will had been sitting"],"k":"C","sk":"Uses perfect verb tenses","b":"221–230","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses commas correctly?","o":["The tired, hungry, hikers finally reached camp.","The, tired hungry hikers finally reached camp.","The tired hungry, hikers finally reached camp.","The tired, hungry hikers finally reached camp."],"k":"D","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["our class read about the Industrial Revolution in history.","Our class read about the industrial revolution in history.","Our class read about the Industrial Revolution in history.","Our class read about the Industrial revolution in History."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["Al-Ula, an ancient city in the northwest, attracts many visitors.","Al-Ula an ancient city in the northwest, attracts many visitors.","Al-Ula, an ancient city in the northwest attracts many visitors.","Al-Ula an ancient city, in the northwest attracts many visitors."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":36,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“The bus is late again” Hind complained.","“The bus is late again,” Hind complained.","“The bus is late again.” Hind complained.","“The bus is late again,” hind complained."],"k":"B","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses an apostrophe correctly?","o":["The childrens laughter filled the park.","The children’s laughter filled the park.","The children’s laughter filled the park’s.","The childrens’ laughter filled the park."],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which title is capitalized correctly?","o":["a Day at the Beach","A day at the beach","A Day at the Beach","A Day At The Beach"],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses a hyphen correctly?","o":["They live in a two story house-.","They live in a-two story house.","They live in a two story-house.","They live in a two-story house."],"k":"D","sk":"Uses hyphens and dashes correctly","b":"201–210","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses a colon correctly?","o":["The recipe needs only three ingredients: flour, water and salt.","The recipe needs only three: ingredients flour, water and salt.","The recipe needs: only three ingredients flour, water and salt.","The recipe: needs only three ingredients flour, water and salt."],"k":"A","sk":"Uses semicolons and colons correctly","b":"201–210","g":"ME"},{"n":41,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Anyone who wants to join the team, must sign up today.","Anyone, who wants to join the team, must sign up today.","Anyone who wants to join the team must sign up today.","Anyone, who wants to join the team must sign up today."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":42,"t":"mc","s":"Which sentence uses a semicolon correctly?","o":["I wanted to go swimming; however, the pool was closed.","I wanted to go swimming, however; the pool was closed.","I wanted to go; swimming however, the pool was closed.","I wanted to go swimming however the pool; was closed."],"k":"A","sk":"Uses semicolons and colons correctly","b":"221–230","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["ocurrence","occurrance","occurence","occurrence"],"k":"D","sk":"Spells grade-level words correctly","b":"221–230","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"C","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"Ibn Sina, Physician and Philosopher","genre":"draft","paras":["(1) Ibn Sina known in Europe as Avicenna, was born near Bukhara around the year 980. (2) By the age of eighteen, he has already become a skilled doctor. (3) His most famous work, The Canon of Medicine, organized everything that was known about medicine at the time. (4) For hundreds of years, doctors in Europe and the Middle East studied it. (5) The Canon described how diseases spread and how they could be treated. (6) He also wrote about philosophy, mathematics, astronomy and music. (7) Today, he is remembered as one of the greatest thinkers in history."],"intro":"Mishal is writing a biography report. Read his draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"What is the correct way to begin sentence 1?","o":["Ibn Sina, known in Europe as Avicenna, was born","Ibn Sina known in Europe as Avicenna, was born","Ibn Sina known in Europe as Avicenna was, born","Ibn Sina, known in Europe, as Avicenna was born"],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":2,"t":"mc","s":"Which sentence BEST supports the idea that Ibn Sina’s book was important?","o":["sentence 1","sentence 2","sentence 4","sentence 6"],"k":"C","sk":"Chooses relevant evidence to support a point","b":"191–200","g":"WR"},{"n":3,"t":"mc","s":"Which words should replace “has already become” in sentence 2?","o":["have already become","has already became","had already became","had already become"],"k":"D","sk":"Uses perfect verb tenses","b":"201–210","g":"GU"},{"n":4,"t":"mc","s":"Which transition could BEST begin sentence 6 to show that it adds new information?","o":["As a result,","Beyond medicine,","In contrast,","For this reason,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":5,"t":"mc","s":"Which sentence could be added after sentence 5 to give a specific example?","o":["Medicine is the study of how to keep people healthy and how to treat their diseases.","For example, it explained that some illnesses could spread through water and soil.","Bukhara is a historic city in present-day Uzbekistan with many old buildings.","Many hospitals today have doctors, nurses and pharmacists who work together."],"k":"B","sk":"Adds a detail that supports the main idea","b":"211–220","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would make the BEST introduction before sentence 1?","o":["Doctors are people who help us when we are sick, and there are many doctors in the world today.","This report is about Ibn Sina, who was a person who lived a very long time ago in history.","Long before modern hospitals, one young man wrote a medical book that doctors would use for centuries.","I chose to write about Ibn Sina because I think he is interesting and I wanted to learn more about him."],"k":"C","sk":"Chooses an effective introduction","b":"211–220","g":"WR"}]},{"passage":{"title":"The Rescue at the Beach","genre":"draft","paras":["(1) The waves at Half Moon Bay were higher than usual that afternoon. (2) My little brother, who had wandered too far from shore, suddenly disappeared under a wave. (3) Without thinking, I ran into the water. (4) The cold waves pushed against my legs. (5) Swimming as hard as I could, his arm was finally in my hand. (6) He coughed and cried, but he was safe. (7) Later, my mother hugged both of us and whispered “I am so proud of you.”"],"intro":"Lamya wrote a personal narrative. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which phrase in sentence 3 shows that Lamya acted immediately?","o":["Without thinking","the water","into the water","I ran"],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"191–200","g":"WR"},{"n":8,"t":"mc","s":"Which revision of sentence 4 uses the MOST vivid sensory language?","o":["The waves were cold, and they were pushing on my legs a lot at that time.","The cold waves were moving, and they touched my legs then.","The water was cold, and it was very wet and also very cold.","Icy waves slammed against my legs and stung my skin like needles."],"k":"D","sk":"Chooses precise or vivid language","b":"201–210","g":"WR"},{"n":9,"t":"mc","s":"What is the correct way to write sentence 7?","o":["Later, my mother hugged both of us and whispered, “I am so proud of you.”","Later, my mother hugged both of us and whispered. “I am so proud of you.”","Later, my mother hugged both of us and whispered, “i am so proud of you.”","Later, my mother hugged both of us and whispered “I am so proud of you”."],"k":"A","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":10,"t":"mc","s":"Why does Lamya include the detail “who had wandered too far from shore” in sentence 2?","o":["to show that her mother was nearby","to explain how to swim safely in big ocean waves","to describe the color of the water","to explain why her brother was in danger"],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":11,"t":"mc","s":"Which revision of sentence 5 corrects the dangling modifier?","o":["His arm, swimming as hard as I could, was finally in my hand.","Swimming as hard as I could, I finally grabbed his arm.","Swimming as hard as I could, finally his arm was in my hand.","Swimming as hard as I could, his arm was finally grabbed."],"k":"B","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":12,"t":"mc","s":"Which sentence would BEST end the narrative?","o":["Half Moon Bay is a popular beach near the city of Khobar on the Gulf coast.","Waves are formed when wind blows across the surface of the ocean for a long time.","That day, I learned that courage sometimes means acting before fear can stop you.","My brother is six years old, and he loves building sandcastles with his friends."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"A Letter About Lunch Waste","genre":"draft","paras":["Dear Mr. Al-Mutairi:","(1) Every day, our cafeteria throws away large amounts of uneaten food. (2) Last week, my classmates and I counted the trays, and we found that nearly one third of the food was wasted. (3) I would like to suggest two changes. (4) First, students could choose their own portion sizes. (5) Second, the school could donate unopened food to a local charity. (6) Some staff members may worry that these changes would take extra time. (7) However the student council have already offered to help organize the program.","Sincerely,","Ziad"],"intro":"Ziad wrote a letter to his principal. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"What is the main purpose of Ziad’s letter?","o":["to explain how to count trays in a cafeteria","to thank the principal for a new lunch menu","to complain about the taste of the food served in the cafeteria","to propose ways to reduce food waste in the cafeteria"],"k":"D","sk":"Chooses language that fits the purpose and audience","b":"191–200","g":"WR"},{"n":14,"t":"mc","s":"Where should a comma be added in sentence 7?","o":["after “council”","after “However”","after “already”","after “help”"],"k":"B","sk":"Uses a comma after an introductory word, phrase or clause","b":"191–200","g":"ME"},{"n":15,"t":"mc","s":"Which word should replace “have” in sentence 7?","o":["having","were","has","are"],"k":"C","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":16,"t":"mc","s":"How does sentence 2 strengthen Ziad’s letter?","o":["It gives evidence that shows the problem is real.","It explains how the charity will use the food.","It responds to the concern in sentence 6.","It describes the menu in the cafeteria."],"k":"A","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":17,"t":"mc","s":"Which sentence acknowledges a possible objection to Ziad’s ideas?","o":["sentence 3","sentence 4","sentence 5","sentence 6"],"k":"D","sk":"Acknowledges and answers an opposing claim","b":"201–210","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would be the MOST effective closing for the letter?","o":["If you say no, then everyone will know that you do not care about wasting food.","Thank you for considering these ideas; I would be glad to meet and discuss them.","I hope you write back, because I really want to know what you think, okay?","Food is important, and wasting it is bad, so please do something about it now."],"k":"B","sk":"Keeps a consistent formal style and objective tone","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which transition BEST shows the relationship between the ideas?\n“The museum was crowded. ___, we decided to visit another day.”","o":["Consequently","Meanwhile","For example","Likewise"],"k":"A","sk":"Chooses a transition that connects ideas","b":"191–200","g":"WR"},{"n":20,"t":"mc","s":"Which revision removes the redundancy?\n“The two twins arrived at the same time together.”","o":["The two twins arrived together at once.","The two twins arrived at the same time.","The twins arrived together.","The twins arrived at the same time together."],"k":"C","sk":"Revises to remove wordy or repeated language","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Which sentence is MOST appropriate for a formal research paper?","o":["Basically, recycling went up a bunch after they started the program.","The data show that recycling rates rose by 12 percent after the program began.","Recycling rates went up, like, a lot after the program started.","The numbers show that way more people started recycling after that, which is totally awesome."],"k":"B","sk":"Keeps a consistent formal style and objective tone","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which group of words is an independent clause?","o":["the students cheered loudly","after the final game of the season","because they won","when the bell rang"],"k":"A","sk":"Identifies phrases and clauses and their functions","b":"191–200","g":"GU"},{"n":23,"t":"mc","s":"Which word correctly completes the sentence?\n“The results of the experiment ___ surprising.”","o":["was","is","were","has been"],"k":"C","sk":"Makes subjects and verbs agree","b":"191–200","g":"GU"},{"n":24,"t":"mc","s":"Which words correctly complete the sentence?\n“The children have ___ all of the cookies.”","o":["eated","eat","ate","eaten"],"k":"D","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"},{"n":25,"t":"mc","s":"Which sentence has a misplaced modifier?","o":["My sister got a puppy that loves to play fetch.","We bought my sister a puppy that loves to play fetch.","We bought a puppy for my sister that loves to play fetch.","For my sister, we bought a puppy that loves to play fetch."],"k":"C","sk":"Places modifiers correctly","b":"201–210","g":"GU"},{"n":26,"t":"mc","s":"Which sentence uses pronouns correctly?","o":["The teacher gave Omar and himself extra time.","The teacher gave he and Omar extra time.","The teacher gave Omar and he extra time.","The teacher gave Omar and him extra time."],"k":"D","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":27,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“The scientist studied the volcano. She wanted to predict eruptions.”","o":["The scientist studied the volcano because she wanted to predict eruptions.","Studying the volcano, eruptions were predicted by the scientist.","The scientist studied the volcano, she wanted to predict eruptions.","The scientist studied the volcano, and wanting to predict its next eruptions."],"k":"A","sk":"Combines sentences correctly","b":"201–210","g":"GU"},{"n":28,"t":"mc","s":"Which sentence uses parallel structure?","o":["She likes to paint, singing and to dance.","She likes to paint, to sing and to dance.","She likes painting, to sing and dancing.","She likes to paint, sing and dancing."],"k":"B","sk":"Uses parallel structure","b":"201–210","g":"GU"},{"n":29,"t":"mc","s":"Which sentence is a compound-complex sentence?","o":["We took a taxi home from the airport late at night.","Because it was very late at night, we took a taxi home from the airport.","It was very late, and so we took a taxi home from the airport that night.","Because it was late, we took a taxi, and my father paid the driver."],"k":"D","sk":"Forms simple, compound and complex sentences","b":"211–220","g":"GU"},{"n":30,"t":"mc","s":"Which sentence has a dangling modifier?","o":["I was reading the book when the doorbell rang.","While reading the book, the doorbell rang.","The doorbell rang while I was reading the book.","While I was reading the book, the doorbell rang."],"k":"B","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which word correctly completes the sentence?\n“Either the players or the coach ___ the equipment.”","o":["carry","are carrying","carries","have carried"],"k":"C","sk":"Uses correlative conjunctions","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which sentence uses the correct verb forms?","o":["If I had known about the party, I would have come.","If I would have known about the party, I would have come.","If I knew about the party, I would have came.","If I had knew about the party, I would have come."],"k":"A","sk":"Uses perfect verb tenses","b":"221–230","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses commas correctly?","o":["We swam, in the clear calm water.","We swam in the clear, calm water.","We swam in the clear calm, water.","We swam in the, clear calm water."],"k":"B","sk":"Uses commas between coordinate adjectives","b":"191–200","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["We visited the King fahd Fountain in jeddah during Ramadan.","We visited the king Fahd fountain in Jeddah during ramadan.","We visited the King Fahd Fountain in Jeddah during ramadan.","We visited the King Fahd Fountain in Jeddah during Ramadan."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"191–200","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["My sister, who is a nurse, works at night.","My sister who is a nurse, works at night.","My sister who, is a nurse works at night.","My sister, who is a nurse works at night."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"191–200","g":"ME"},{"n":36,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“Did you finish the report.” asked Mr. Hamdan?","“Did you finish the report?” Asked Mr. Hamdan.","“Did you finish the report?” asked Mr. Hamdan.","“Did you finish the report,” asked Mr. Hamdan?"],"k":"C","sk":"Punctuates dialogue and quotations","b":"191–200","g":"ME"},{"n":37,"t":"mc","s":"Which title should be written in quotation marks?","o":["the title of a movie","the title of a novel","the title of a newspaper article","the name of a weekly news magazine"],"k":"C","sk":"Capitalizes and punctuates titles of works","b":"191–200","g":"ME"},{"n":38,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["The players’s uniforms were washed after the game.","The players’ uniforms were washed after the game.","The players uniforms’ were washed after the game.","The player’s uniforms were washed after the games’."],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses a hyphen correctly?","o":["She gave a twenty minute speech-.","She gave a twenty minute-speech.","She gave a-twenty minute speech.","She gave a twenty-minute speech."],"k":"D","sk":"Uses hyphens and dashes correctly","b":"201–210","g":"ME"},{"n":40,"t":"mc","s":"Which sentence is punctuated correctly?","o":["The car that my father bought is blue.","The car, that my father bought is blue.","The car, that my father bought, is blue.","The car that my father bought, is blue."],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":41,"t":"mc","s":"Which sentence uses a semicolon correctly?","o":["The rain stopped the; sun came out.","The rain; stopped the sun came out.","The rain stopped; and the sun came out.","The rain stopped; the sun came out."],"k":"D","sk":"Uses semicolons and colons correctly","b":"211–220","g":"ME"},{"n":42,"t":"mc","s":"Which word is spelled correctly?","o":["privilage","privilege","priviledge","privelege"],"k":"B","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"},{"n":43,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Hessa said “The coach told us, ‘Practice makes progress.’”","Hessa said, “The coach told us, “Practice makes progress.””","Hessa said, “The coach told us, ‘Practice makes progress.’”","Hessa said, “The coach told us, Practice makes progress.”"],"k":"C","sk":"Punctuates dialogue and quotations","b":"221–230","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"D","note":"Full practice test · 43 questions · harder","sections":[{"passage":{"title":"Hegra: City of the Nabataeans","genre":"draft","paras":["(1) In the desert of northwestern Saudi Arabia lies Hegra, an ancient city carved from rock. (2) It was built by the Nabataeans more than two thousand years ago. (3) The Nabataeans grew wealthy by controlling trade routes for incense and spices. (4) At Hegra, they carved more than one hundred tombs into the sandstone cliffs. (5) Many of the tombs have detailed decorations above their doorways. (6) In 2008, Hegra became Saudi Arabias first UNESCO World Heritage Site. (7) Visitors from around the world now come to see the tombs, which has survived for centuries."],"intro":"Lujain is writing a history report. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"How should “Saudi Arabias” be written in sentence 6?","o":["Saudi Arabia’s","Saudi Arabias’","Saudi’s Arabia","Saudi Arabia’s’"],"k":"A","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":2,"t":"mc","s":"Which sentence would BEST follow sentence 3 to explain it?","o":["Trade is the buying and selling of goods between people or countries.","Merchants paid them to travel safely through the lands they controlled.","Incense is a substance that gives off a sweet smell when it is burned.","Spices such as pepper and cinnamon are still popular in cooking today."],"k":"B","sk":"Adds a detail that supports the main idea","b":"201–210","g":"WR"},{"n":3,"t":"mc","s":"Which words should replace “which has survived” in sentence 7?","o":["which have survive","which has survive","which surviving","which have survived"],"k":"D","sk":"Makes subjects and verbs agree","b":"211–220","g":"GU"},{"n":4,"t":"mc","s":"Lujain wants to add a sentence describing the carvings of eagles and snakes on the tombs. Where should it go?","o":["after sentence 1","after sentence 2","after sentence 5","after sentence 7"],"k":"C","sk":"Puts sentences or events in a logical order","b":"211–220","g":"WR"},{"n":5,"t":"mc","s":"Which revision of sentence 2 is the MOST precise?","o":["It was built by the Nabataeans, an Arab people who flourished in the first century BCE.","It was built by the Nabataeans, who were people who lived there a long, long time ago.","It was built by some people a very long time ago in the past, more than two thousand years.","It was built by the Nabataeans, and they were very good at building things back then."],"k":"A","sk":"Chooses precise or vivid language","b":"211–220","g":"WR"},{"n":6,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["UNESCO is an organization of the United Nations that works in education, science and culture.","The northwestern part of Saudi Arabia has mountains, valleys and wide deserts.","Standing among the tombs of Hegra, visitors can glimpse the genius of a lost civilization.","Sandstone is a type of rock made from grains of sand pressed together over time."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"The Night Market","genre":"draft","paras":["(1) The night market came alive as soon as the sun went down. (2) Strings of lights swung above the stalls and the smell of grilled corn filled the air. (3) My grandmother held my hand tightly as we wove through the crowd. (4) Suddenly, I spotted a stall selling hand-painted lanterns. (5) I let go of her hand to look closer. (6) When I turned around, she was gone. (7) My heart pounded as I search the sea of faces."],"intro":"Nada is writing a story. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Where should a comma be added in sentence 2?","o":["after “lights”","after “stalls”","after “corn”","after “smell”"],"k":"B","sk":"Uses a comma before a conjunction in a compound sentence","b":"201–210","g":"ME"},{"n":8,"t":"mc","s":"Which word should replace “search” in sentence 7?","o":["have searched","searching","searches","searched"],"k":"D","sk":"Avoids inappropriate shifts in verb tense","b":"201–210","g":"GU"},{"n":9,"t":"mc","s":"Which phrase in sentence 2 appeals to the sense of smell?","o":["swung above","the smell of grilled corn","above the stalls","Strings of lights swung above"],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":10,"t":"mc","s":"What is the effect of the short sentence 6?","o":["It creates a sudden moment of fear.","It shows that the narrator is calm.","It explains where the grandmother went.","It describes the lanterns in the stall."],"k":"A","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":11,"t":"mc","s":"Which sentence could be added after sentence 7 to continue building tension?","o":["Night markets are popular in many cities during holidays.","My grandmother is seventy years old and loves to cook.","The lanterns at the stall were painted red, blue and gold.","Every gray head scarf I saw belonged to a stranger."],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"211–220","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST resolution for the story?","o":["Lanterns have been used for hundreds of years to light streets and homes at night.","The market closes at midnight, and the sellers pack their stalls into small trucks.","Then I heard my name, and there she was, holding a lantern she had bought for me.","Grilled corn is a popular snack that is often sold with salt, lemon and chili powder."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"}]},{"passage":{"title":"Is Esports a Real Sport?","genre":"draft","paras":["(1) Competitive video gaming, known as esports, should be recognized as a real sport. (2) Like traditional athletes, esports players train for many hours each day. (3) They must have fast reflexes, sharp focus and strong teamwork. (4) Critics claim that esports cannot be a sport because players do not move their bodies much. (5) However, sports such as archery and shooting also require little running, yet they are part of the olympic games. (6) Saudi Arabia has even hosted major esports tournaments with players from around the world. (7) Esports demands skill, discipline and competing at a high level, so it deserves to be called a sport."],"intro":"Khalid wrote an argument essay. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states Khalid’s claim?","o":["sentence 1","sentence 2","sentence 4","sentence 6"],"k":"A","sk":"States a clear claim or thesis","b":"201–210","g":"WR"},{"n":14,"t":"mc","s":"What is the correct way to write the end of sentence 5?","o":["part of The Olympic Games.","part of the Olympic games.","part of the olympic Games.","part of the Olympic Games."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"201–210","g":"ME"},{"n":15,"t":"mc","s":"Which transition could BEST begin sentence 6 to show that it adds support?","o":["Otherwise,","In addition,","Nevertheless,","In contrast,"],"k":"B","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":16,"t":"mc","s":"Which evidence would BEST support sentence 2?","o":["Some video games are designed for one player, while others can have dozens of players at once.","Many families enjoy playing board games together on weekends and during the holidays.","Many professional esports teams practice six to ten hours a day with coaches and trainers.","Video games were first sold in stores in the 1970s, and they have changed a great deal since then."],"k":"C","sk":"Chooses relevant evidence to support a point","b":"201–210","g":"WR"},{"n":17,"t":"mc","s":"Which word should replace “competing” in sentence 7?","o":["competition","to compete","competes","compete"],"k":"A","sk":"Uses parallel structure","b":"211–220","g":"GU"},{"n":18,"t":"mc","s":"How does sentence 5 respond to the counterclaim?","o":["It introduces a new claim about the Olympic Games.","It agrees that esports players should exercise and move their bodies more often.","It explains the rules and scoring of archery and shooting competitions in detail.","It gives examples of accepted sports that also require little movement."],"k":"D","sk":"Acknowledges and answers an opposing claim","b":"211–220","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which sentence is the MOST concise?","o":["Please reply by Friday, which is the day that comes after Thursday.","Please reply by Friday.","Please respond and reply to me by Friday at the latest.","Please reply back to me by the day of Friday."],"k":"B","sk":"Revises to remove wordy or repeated language","b":"201–210","g":"WR"},{"n":20,"t":"mc","s":"Which sentence BEST keeps a formal style in a lab report?","o":["The stuff in the cup turned a weird color after a bit.","After like three minutes, the liquid went all purple.","The solution changed color after three minutes.","The solution totally changed color, which was so cool."],"k":"C","sk":"Keeps a consistent formal style and objective tone","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Read the sentence from a source.\n“The cheetah can accelerate from zero to one hundred kilometers per hour in about three seconds.”\nWhich sentence paraphrases it accurately?","o":["The cheetah can accelerate from zero to one hundred kilometers per hour in about three seconds.","In roughly three seconds, a cheetah can go from standing still to one hundred kilometers per hour.","In about one hundred seconds, a cheetah can reach a speed of three kilometers per hour.","A cheetah can run one hundred kilometers without stopping in about three hours."],"k":"B","sk":"Paraphrases or cites a source correctly","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which group of words is a dependent clause?","o":["near the open store","the store was open","opening the doors of the store","although the store was open"],"k":"D","sk":"Identifies phrases and clauses and their functions","b":"201–210","g":"GU"},{"n":23,"t":"mc","s":"Which sentence is a compound sentence?","o":["Studying hard, Hamad passed the exam.","Because Hamad studied hard, he passed the exam.","Hamad studied hard, and he passed the exam.","Hamad passed the exam after studying hard."],"k":"C","sk":"Forms simple, compound and complex sentences","b":"201–210","g":"GU"},{"n":24,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“The principal congratulated Maha and ___ on our project.”","o":["me","I","myself","mine"],"k":"A","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":25,"t":"mc","s":"Which sentence uses the correct form of the verb?","o":["The sun has rose over the hills.","The sun has risen over the hills.","The sun has rised over the hills.","The sun has rosen over the hills."],"k":"B","sk":"Forms irregular past-tense and past-participle verbs","b":"201–210","g":"GU"},{"n":26,"t":"mc","s":"Which word correctly completes the sentence?\n“Everyone in the two classes ___ invited to the ceremony.”","o":["have been","were","was","are"],"k":"C","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":27,"t":"mc","s":"Which sentence has a misplaced modifier?","o":["While walking along the beach, Nawaf found a ring.","Nawaf found a ring while he was walking along the beach.","Walking along the beach, Nawaf found a ring.","Nawaf found a ring walking along the beach."],"k":"D","sk":"Places modifiers correctly","b":"201–210","g":"GU"},{"n":28,"t":"mc","s":"Which sentence is a compound-complex sentence?","o":["When the guests arrived, we served dinner, and everyone enjoyed the food.","When the guests arrived, we served a delicious dinner to everyone in the room.","We served dinner to the guests as soon as they arrived at the house.","The guests arrived, and we served them a delicious dinner of rice and fish."],"k":"A","sk":"Forms simple, compound and complex sentences","b":"211–220","g":"GU"},{"n":29,"t":"mc","s":"Which sentence has a dangling modifier?","o":["After we had eaten dinner, we washed the dishes.","Having eaten dinner, the dishes were washed.","Having eaten dinner, we washed the dishes.","We washed the dishes after eating dinner."],"k":"B","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":30,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“Hessa entered the contest. She won first place. She was only twelve.”","o":["Hessa entered the contest and won first place, only twelve was she.","Hessa entered the contest, she won first place, she was only twelve.","Hessa, who was only twelve, entered the contest and won first place.","Entering the contest, first place was won by Hessa, only twelve."],"k":"C","sk":"Combines sentences correctly","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which sentence uses parallel structure?","o":["The tour includes to visit the fort, touring the museum and lunch eating.","The tour includes a visit to the fort, touring the museum and to eat.","The tour includes visiting the fort, a museum tour and to eat lunch.","The tour includes visiting the fort, touring the museum and eating lunch."],"k":"D","sk":"Uses parallel structure","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"Which words correctly complete the sentence?\n“If the team ___ harder, they would have won.”","o":["had practiced","has practiced","practices","would practice"],"k":"A","sk":"Uses perfect verb tenses","b":"221–230","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses commas correctly?","o":["The soft, warm, blanket kept me cozy.","The soft, warm blanket kept me cozy.","The soft warm, blanket kept me cozy.","The, soft warm blanket kept me cozy."],"k":"B","sk":"Uses commas between coordinate adjectives","b":"201–210","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["Every year, my family celebrates Saudi National day on september 23.","Every Year, my family celebrates Saudi National Day on September 23.","Every year, my family celebrates Saudi National Day on September 23.","Every year, my family celebrates saudi national day on September 23."],"k":"C","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"201–210","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["Dr. Khalid, the dentist on our street is very gentle.","Dr. Khalid the dentist on our street, is very gentle.","Dr. Khalid the dentist, on our street is very gentle.","Dr. Khalid, the dentist on our street, is very gentle."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":36,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“Look at the stars!” exclaimed Turki.","“Look at the stars,” exclaimed Turki!","“Look at the stars!” Exclaimed Turki.","“Look at the stars” exclaimed Turki!"],"k":"A","sk":"Punctuates dialogue and quotations","b":"201–210","g":"ME"},{"n":37,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["The two brothers room was always messy.","The two brother’s room was always messy.","The two brothers’ room was always messy.","The two brothers’s room was always messy."],"k":"C","sk":"Uses apostrophes in contractions and possessives","b":"201–210","g":"ME"},{"n":38,"t":"mc","s":"Which sentence uses a semicolon correctly?","o":["The sky darkened a storm; was coming.","The sky darkened; and a storm was coming.","The sky; darkened a storm was coming.","The sky darkened; a storm was coming."],"k":"D","sk":"Uses semicolons and colons correctly","b":"201–210","g":"ME"},{"n":39,"t":"mc","s":"Which sentence uses a colon correctly?","o":["The team had one goal: to win the championship.","The team had: one goal to win the championship.","The team had one: goal to win the championship.","The team: had one goal to win the championship."],"k":"A","sk":"Uses semicolons and colons correctly","b":"201–210","g":"ME"},{"n":40,"t":"mc","s":"Which title should be written in italics or underlined?","o":["the title of a short poem","the title of a full-length play","the title of a magazine article","the title of an episode of a series"],"k":"B","sk":"Capitalizes and punctuates titles of works","b":"201–210","g":"ME"},{"n":41,"t":"mc","s":"Which sentence is punctuated correctly?","o":["The phone, that I lost was found in the gym.","The phone that I lost, was found in the gym.","The phone, that I lost, was found in the gym.","The phone that I lost was found in the gym."],"k":"D","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":42,"t":"mc","s":"Which word is spelled correctly?","o":["gaurantee","guarentee","guarantee","garantee"],"k":"C","sk":"Spells grade-level words correctly","b":"211–220","g":"ME"},{"n":43,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Lama said, “My grandmother always says, Patience is beautiful.”","Lama said, “My grandmother always says, ‘Patience is beautiful.’”","Lama said “My grandmother always says, ‘Patience is beautiful.’”","Lama said, “My grandmother always says, “Patience is beautiful.””"],"k":"B","sk":"Punctuates dialogue and quotations","b":"221–230","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]},{"id":"E","note":"Final full practice test · 43 questions · hardest","sections":[{"passage":{"title":"Microplastics: A Hidden Problem","genre":"draft","paras":["(1) Microplastics are tiny pieces of plastic smaller than five millimeters. (2) They form when larger plastic items, such as bottles and bags, break down over time. (3) Some microplastics also come from clothing; washing machines release tiny fibers into the water. (4) These particles have been found in oceans, rivers, soil and even the air. (5) Fish and other sea animals often mistakes microplastics for food. (6) Scientists are still studying how microplastics affect human health, however the early results are concerning. (7) Reducing plastic use is one way that each of us can help."],"intro":"Dana is writing a science report. Read her draft and answer the questions."},"items":[{"n":1,"t":"mc","s":"Which word should replace “mistakes” in sentence 5?","o":["is mistaking","has mistaken","mistaking","mistake"],"k":"D","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":2,"t":"mc","s":"Which sentence BEST states the main idea of the report?","o":["Plastic bottles and bags are used by many people around the world every day.","The ocean covers most of the planet and contains many kinds of sea animals.","Microplastics are a widespread form of pollution that may harm living things.","Washing machines are useful machines that clean clothes with soap and water."],"k":"C","sk":"Chooses a topic sentence that introduces the main idea","b":"201–210","g":"WR"},{"n":3,"t":"mc","s":"Which source would be the MOST useful for evidence about sentence 4?","o":["an advertisement for a new kind of water bottle","a report by an environmental research institute","a social media post about a trip to the beach","a novel about sailors who are lost at sea"],"k":"B","sk":"Chooses a useful source or research question","b":"201–210","g":"WR"},{"n":4,"t":"mc","s":"Which sentence could be added after sentence 5 to explain why this is a problem?","o":["When animals eat plastic, they may feel full and stop eating real food.","Plastic was first produced on a large scale in the twentieth century.","Many kinds of fish live in coral reefs, where the water is warm and clear.","Some people prefer to eat fish that has been grilled with lemon and herbs."],"k":"A","sk":"Adds a detail that supports the main idea","b":"211–220","g":"WR"},{"n":5,"t":"mc","s":"Which sentence would be the BEST conclusion for the report?","o":["Plastic can be made in many colors and shapes, which is why it is used for toys.","Some rivers flow for thousands of kilometers before they reach the ocean.","Small choices, such as carrying a reusable bottle, can add up to a cleaner planet.","The air we breathe is made mostly of nitrogen and oxygen, along with other gases."],"k":"C","sk":"Chooses an effective concluding sentence","b":"211–220","g":"WR"},{"n":6,"t":"mc","s":"What is the correct way to write sentence 6?","o":["Scientists are still studying how microplastics affect human health; however, the early results are concerning.","Scientists are still studying how microplastics affect human health, however, the early results are concerning.","Scientists are still studying how microplastics affect human health however; the early results are concerning.","Scientists are still studying how microplastics affect human health; however the early results, are concerning."],"k":"A","sk":"Uses semicolons and colons correctly","b":"221–230","g":"ME"}]},{"passage":{"title":"The Last Day at the Old School","genre":"draft","paras":["(1) On the last day before our old school was torn down, I walked through the empty halls one final time. (2) The lockers which had once been bright blue, were now faded and dented. (3) I stopped outside room 12, where I had learned to read. (4) Through the dusty window, I could almost see my first-grade teacher writing on the board. (5) My friend Noor, who had been at the school as long as I had, stood quietly beside me. (6) “Do you think they’ll remember us?” she whispered. (7) I didn’t answer, I just took one last look and walked toward the door."],"intro":"Yara wrote a personal narrative. Read her draft and answer the questions."},"items":[{"n":7,"t":"mc","s":"Which word in sentence 2 BEST shows that time has passed?","o":["bright","faded","blue","lockers"],"k":"B","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":8,"t":"mc","s":"What is the purpose of the dialogue in sentence 6?","o":["to explain exactly when the new school building will be finished","to describe what room 12 looks like inside","to show that Noor is angry with the narrator","to reveal Noor’s worry that they will be forgotten"],"k":"D","sk":"Uses narrative techniques: dialogue, description and pacing","b":"201–210","g":"WR"},{"n":9,"t":"mc","s":"What is the correct way to write the beginning of sentence 2?","o":["The lockers, which had once been bright blue,","The lockers which had once been bright blue","The lockers which, had once been bright blue,","The lockers, which had once been, bright blue"],"k":"A","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":10,"t":"mc","s":"What is the BEST way to fix sentence 7?","o":["I didn’t answer I just took one last look and walked toward the door.","I didn’t answer, I just, took one last look and walked toward the door.","I didn’t answer, and, I just took one last look and walked toward the door.","I didn’t answer; I just took one last look and walked toward the door."],"k":"D","sk":"Recognizes complete sentences, fragments and run-ons","b":"211–220","g":"GU"},{"n":11,"t":"mc","s":"Why does Yara include the detail in sentence 4?","o":["to show that the window needs to be cleaned","to describe what the first-grade lessons were about","to show how strongly the place brings back memories","to explain why the school is being torn down"],"k":"C","sk":"Uses narrative techniques: dialogue, description and pacing","b":"211–220","g":"WR"},{"n":12,"t":"mc","s":"Which sentence would be the BEST ending for the narrative?","o":["Room 12 was on the second floor, at the end of the hallway near the stairs.","As the door closed behind us, I realized the memories would stay with me wherever I went.","The new school will have a larger library, a science lab and a gym with a swimming pool.","Lockers are usually made of strong metal so that they can last for many years in busy schools."],"k":"B","sk":"Chooses an effective concluding sentence","b":"221–230","g":"WR"}]},{"passage":{"title":"Our City Needs Better Public Transportation","genre":"draft","paras":["(1) Our city should invest in a modern public transportation system. (2) Traffic jams waste thousands of hours each year, and add pollution to the air. (3) A network of buses and trains would reduce the number of cars on the road. (4) In cities with strong public transportation, residents spend less money on fuel and car repairs. (5) Opponents argue that such a system would be too expensive to build. (6) However, the long-term savings in health costs, time and fuel would be far greater then the initial cost. (7) The Riyadh Metro, which opened in 2024, shows that a city in our region can successfully build such a system."],"intro":"Fahad wrote an argument essay. Read his draft and answer the questions."},"items":[{"n":13,"t":"mc","s":"Which sentence states Fahad’s claim?","o":["sentence 1","sentence 3","sentence 5","sentence 7"],"k":"A","sk":"States a clear claim or thesis","b":"191–200","g":"WR"},{"n":14,"t":"mc","s":"Which word should replace “then” in sentence 6?","o":["thin","than","that","them"],"k":"B","sk":"Chooses between frequently confused words","b":"201–210","g":"GU"},{"n":15,"t":"mc","s":"Which sentence acknowledges an opposing view?","o":["sentence 2","sentence 4","sentence 5","sentence 6"],"k":"C","sk":"Acknowledges and answers an opposing claim","b":"201–210","g":"WR"},{"n":16,"t":"mc","s":"Which revision of sentence 2 is punctuated correctly?","o":["Traffic jams, waste thousands of hours each year and add pollution to the air.","Traffic jams waste thousands of hours each year and, add pollution to the air.","Traffic jams waste thousands of hours, each year, and add pollution to the air.","Traffic jams waste thousands of hours each year and add pollution to the air."],"k":"D","sk":"Uses a comma before a conjunction in a compound sentence","b":"211–220","g":"ME"},{"n":17,"t":"mc","s":"How does sentence 7 strengthen the argument?","o":["It introduces an opposing view that the writer disagrees with.","It gives a real example showing that the plan is possible.","It repeats the claim using exactly the same words as before.","It explains how trains are built and how they are powered."],"k":"B","sk":"Chooses relevant evidence to support a point","b":"211–220","g":"WR"},{"n":18,"t":"mc","s":"Which sentence would be the BEST conclusion to add after sentence 7?","o":["By investing in public transportation now, our city can become cleaner, healthier and easier to travel.","Buses come in many sizes, and some of them can carry more than one hundred passengers at once.","Trains can travel on tracks above the ground, below the ground or at street level in many large cities around the world.","Some people enjoy driving their own cars because they like to listen to music while they drive."],"k":"A","sk":"Chooses an effective concluding sentence","b":"221–230","g":"WR"}]},{"passage":null,"items":[{"n":19,"t":"mc","s":"Which transition BEST shows the relationship between the sentences?\n“Many students prefer printed textbooks. ___, digital textbooks are lighter and cheaper.”","o":["In the same way","For example","As a result","On the other hand"],"k":"D","sk":"Chooses a transition that connects ideas","b":"201–210","g":"WR"},{"n":20,"t":"mc","s":"Which sentence is the MOST precise?","o":["The hurricane did a lot of really bad things to many of the places that were near it.","The storm was really, really big, and it caused lots and lots of damage everywhere.","The hurricane damaged more than two thousand homes along the coast.","Some stuff got damaged when the huge storm came."],"k":"C","sk":"Chooses precise or vivid language","b":"201–210","g":"WR"},{"n":21,"t":"mc","s":"Which sentence correctly credits a source in a research report?","o":["According to the World Health Organization, air pollution causes millions of deaths each year.","Air pollution causes millions of deaths each year, according to what I heard at school.","Somebody wrote somewhere online that air pollution causes millions of deaths each year.","Air pollution causes millions of deaths each year, and everyone already knows this well-known fact by now."],"k":"A","sk":"Paraphrases or cites a source correctly","b":"211–220","g":"WR"}],"label":"Writing"},{"passage":null,"items":[{"n":22,"t":"mc","s":"Which words correctly complete the sentence?\n“The guests have ___ their seats.”","o":["take","taked","taken","took"],"k":"C","sk":"Forms irregular past-tense and past-participle verbs","b":"191–200","g":"GU"},{"n":23,"t":"mc","s":"Which sentence is a complex sentence?","o":["It snowed; the schools closed early.","Whenever it snows, the schools close early.","The schools close early in the snow.","It snows a lot, and the schools close very early."],"k":"B","sk":"Forms simple, compound and complex sentences","b":"201–210","g":"GU"},{"n":24,"t":"mc","s":"Which pronoun correctly completes the sentence?\n“Between Huda and ___, there are no secrets.”","o":["I","myself","mine","me"],"k":"D","sk":"Uses the correct pronoun case","b":"201–210","g":"GU"},{"n":25,"t":"mc","s":"Which word correctly completes the sentence?\n“The quality of the photos ___ excellent.”","o":["were","are","have been","is"],"k":"D","sk":"Makes subjects and verbs agree","b":"201–210","g":"GU"},{"n":26,"t":"mc","s":"Which sentence uses parallel structure?","o":["The new library has brightness, spacious and modern.","The new library is bright, spacious and modern.","The new library is bright, spacious and has modern style.","The new library is bright, has space and modern."],"k":"B","sk":"Uses parallel structure","b":"201–210","g":"GU"},{"n":27,"t":"mc","s":"Which is the BEST way to combine the sentences?\n“The festival was crowded. We enjoyed it.”","o":["Because the festival was crowded, we enjoyed it.","The festival was crowded, we enjoyed it.","Although the festival was crowded, we enjoyed it.","The festival was crowded, so we enjoyed it."],"k":"C","sk":"Combines sentences correctly","b":"201–210","g":"GU"},{"n":28,"t":"mc","s":"Which sentence has a misplaced modifier?","o":["The teacher returned the tests to the students that were graded.","The teacher returned the graded tests to the students.","The teacher returned the tests, which were graded, to the students.","The students received their graded tests from the teacher."],"k":"A","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":29,"t":"mc","s":"Which sentence has a dangling modifier?","o":["To win the race, you need a lot of practice.","Winning the race requires a lot of practice.","To win the race, a lot of practice is needed.","You need a lot of practice to win the race."],"k":"C","sk":"Places modifiers correctly","b":"211–220","g":"GU"},{"n":30,"t":"mc","s":"Which word correctly completes the sentence?\n“Neither of the answers ___ correct.”","o":["were","is","have been","are"],"k":"B","sk":"Makes subjects and verbs agree","b":"211–220","g":"GU"},{"n":31,"t":"mc","s":"Which words correctly complete the sentence?\n“By the end of the year, the company ___ five new stores.”","o":["has opened","will has opened","had opened","will have opened"],"k":"D","sk":"Uses perfect verb tenses","b":"211–220","g":"GU"},{"n":32,"t":"mc","s":"What is the function of the phrase “to win the game” in this sentence?\n“Our goal is to win the game.”","o":["It renames the subject “goal.”","It tells where the game takes place.","It shows who will win the game.","It describes the verb “is.”"],"k":"A","sk":"Identifies phrases and clauses and their functions","b":"221–230","g":"GU"}],"label":"Grammar and Usage"},{"passage":null,"items":[{"n":33,"t":"mc","s":"Which sentence uses commas correctly?","o":["The narrow crowded, street led to the market.","The narrow, crowded street led to the market.","The, narrow crowded street led to the market.","The narrow, crowded, street led to the market."],"k":"B","sk":"Uses commas between coordinate adjectives","b":"201–210","g":"ME"},{"n":34,"t":"mc","s":"Which sentence is capitalized correctly?","o":["My aunt lives on the East side of Dammam, near the Corniche.","my aunt lives on the east side of dammam, near the corniche.","My Aunt lives on the east side of Dammam, near the corniche.","My aunt lives on the east side of Dammam, near the Corniche."],"k":"D","sk":"Capitalizes proper nouns, titles and sentence beginnings","b":"201–210","g":"ME"},{"n":35,"t":"mc","s":"Which sentence uses commas correctly?","o":["Hassan, my oldest cousin is studying engineering.","Hassan my oldest, cousin is studying engineering.","Hassan, my oldest cousin, is studying engineering.","Hassan my oldest cousin, is studying engineering."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"201–210","g":"ME"},{"n":36,"t":"mc","s":"Which sentence uses a colon correctly?","o":["Remember the rule: always wear a helmet.","Remember the rule always: wear a helmet.","Remember the: rule always wear a helmet.","Remember: the rule always wear a helmet."],"k":"A","sk":"Uses semicolons and colons correctly","b":"201–210","g":"ME"},{"n":37,"t":"mc","s":"Which sentence is punctuated correctly?","o":["“Can we leave now?” asked my brother. “I’m tired.”","“Can we leave now?” asked my brother, “I’m tired.”","“Can we leave now?” Asked my brother. “I’m tired.”","“Can we leave now,” asked my brother. “I’m tired.”"],"k":"A","sk":"Punctuates dialogue and quotations","b":"211–220","g":"ME"},{"n":38,"t":"mc","s":"Which sentence uses apostrophes correctly?","o":["The women’s and mens teams practiced together.","The women’s and men’s teams practiced together.","The womens’ and mens’ teams practiced together.","The womens and men’s teams practiced together."],"k":"B","sk":"Uses apostrophes in contractions and possessives","b":"211–220","g":"ME"},{"n":39,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Any student, who arrives early, can help set up the chairs.","Any student, who arrives early can help set up the chairs.","Any student who arrives early can help set up the chairs.","Any student who arrives early, can help set up the chairs."],"k":"C","sk":"Uses commas, parentheses or dashes to set off extra information","b":"211–220","g":"ME"},{"n":40,"t":"mc","s":"Which sentence uses hyphens correctly?","o":["My eight-year old brother loves dinosaurs.","My eight year-old brother loves dinosaurs.","My eight year old-brother loves dinosaurs.","My eight-year-old brother loves dinosaurs."],"k":"D","sk":"Uses hyphens and dashes correctly","b":"211–220","g":"ME"},{"n":41,"t":"mc","s":"Which sentence uses semicolons correctly?","o":["We visited Abha, Saudi Arabia, Muscat, Oman; and Dubai, United Arab Emirates.","We visited Abha; Saudi Arabia, Muscat; Oman, and Dubai; United Arab Emirates.","We visited; Abha, Saudi Arabia, Muscat, Oman and Dubai, United Arab Emirates.","We visited Abha, Saudi Arabia; Muscat, Oman; and Dubai, United Arab Emirates."],"k":"D","sk":"Uses semicolons and colons correctly","b":"221–230","g":"ME"},{"n":42,"t":"mc","s":"Which sentence is punctuated correctly?","o":["Our coach said, “The referee told me, “Your team played fairly.””","Our coach said, “The referee told me, ‘Your team played fairly.’”","Our coach said “The referee told me, ‘Your team played fairly.’”","Our coach said, “The referee told me, Your team played fairly.”"],"k":"B","sk":"Punctuates dialogue and quotations","b":"221–230","g":"ME"},{"n":43,"t":"mc","s":"Which word is spelled correctly?","o":["maintainance","maintenence","maintenance","maintanance"],"k":"C","sk":"Spells grade-level words correctly","b":"221–230","g":"ME"}],"label":"Capitalization, Punctuation and Spelling"}]}],"pass":[{"title":"Later School Start Times","genre":"draft","paras":["(1) Many teenagers struggle to wake up for school, and the problem is not simply laziness. (2) During the teenage years, the body’s internal clock shifts, so teens naturally fall asleep later at night. (3) Because of this shift, early start times cause many students to miss the sleep they need. (4) Our school should start classes at 8:30 instead of 7:00. (5) Opponents argue that a later start would leave less time for after-school activities. (6) Schools that changed their schedules have found ways to keep their sports and clubs. (7) A later start would help students learn more and feel better."],"intro":"Abdulaziz is writing an argument essay. Read his draft and answer the questions."},{"title":"The Shrinking Dead Sea","genre":"draft","paras":["(1) The Dead Sea, on the border of Jordan, is the lowest place on land on Earth. (2) Its water is so salty that people can float on it easily. (3) Over the past fifty years, however, its surface has dropped by more than thirty meters. (4) The main cause is that much of the water from the Jordan River, which feeds the sea, is now used for farming and drinking. (5) In addition, companies remove water to collect minerals. (6) As the water level falls, large holes called sinkholes have opened along the shore. (7) Some scientists have proposed piping water from the Red Sea to refill it."],"intro":"Jana is writing an informative report that explains a cause-and-effect relationship. Read her draft and answer the questions."},{"title":"The Audition","genre":"draft","paras":["(1) I stood backstage, holding my violin. (2) Through the curtain, I could hear the judges whispering to each other. (3) My name was called. (4) I walked onto the stage. (5) The lights were bright and hot. (6) I lifted my bow and began to play the first notes of the piece I had practiced for months. (7) When the final note faded, the room was silent and quiet for a moment, and then the judges began to clap."],"intro":"Reema is writing a story. Read her draft and answer the questions."},{"title":"Research Notes: Ibn al-Haytham","genre":"draft","paras":["**Source:** From the book Pioneers of Science by Dr. Lina Farouk (2019), page 42: “Ibn al-Haytham, who was born in Basra around 965, is often called the father of modern optics. In his Book of Optics, he argued that we see objects because light reflects off them and enters our eyes. Earlier thinkers believed that the eyes sent out rays. He tested his ideas with careful experiments, an approach that helped shape the scientific method.”","**Draft**","(1) Ibn al-Haytham was a scientist from Basra. (2) He is often called the father of modern optics. (3) Before him, many people believed that our eyes sent out rays in order to see things. (4) Ibn al-Haytham argued that we see objects because light reflects off them and enters our eyes. (5) He tested his ideas with careful experiments. (6) His methods were very, very important and really helped science a lot."],"intro":"Bassam is writing a report about a scientist. Read the source and his draft, then answer the questions."},{"title":"The Museum Trip","genre":"draft","paras":["(1) Last Tuesday, our class visited the National Museum in Riyadh. (2) We saw ancient pottery, we also saw a huge meteorite. (3) Which fell in the Empty Quarter long ago. (4) Our guide explained how scientists study objects. (5) To find out how old they are. (6) I enjoyed the visit so much that I want to go back with my family. (7) The trip taught me that history is all around us."],"intro":"Zainab wrote about a class trip. Her draft has some sentence problems. Read it and answer the questions."},{"title":"Cooking with My Aunt","genre":"draft","paras":["(1) Every Friday, my aunt teaches my cousin and I how to cook. (2) Last week, we made kabsa, a rice dish with chicken and spices. (3) Chopping the onions, tears filled my eyes. (4) My aunt showed us how to measure the spices carefully with a smile. (5) We cooked the rice slowly in a large pot that my grandmother had gave her. (6) While the rice cooked, my cousin and I set the table. (7) Everyone said that it was the best kabsa they had ever tasted."],"intro":"Rayan wrote about a cooking lesson. His draft has some mistakes. Read it and answer the questions."},{"title":"A Visit to Diriyah","genre":"draft","paras":["(1) Last winter, my family visited Diriyah. (2) Diriyah which is on the edge of Riyadh, was the first capital of the Saudi state. (3) We walked through narrow winding streets lined with mud-brick buildings. (4) The At-Turaif district a UNESCO World Heritage Site, was my favorite part. (5) Our guide, who grew up nearby, told us stories about the old palaces. (6) The people, who built these houses, used clay, straw and palm wood. (7) As the sun set the old walls glowed a warm, golden color."],"intro":"Omar wrote about a family trip. His draft has some comma mistakes. Read it and answer the questions."},{"title":"An Interview with a Scientist","genre":"draft","paras":["(1) Last month, I interviewed Dr. Noura Al-Qahtani, a marine biologist at king Abdulaziz university. (2) I asked her, “What made you want to study the ocean”? (3) She smiled and said, “When I was young, my father told me, ‘The sea holds more secrets than the sky.’” (4) Dr. Al-Qahtanis team studies coral reefs in the Red Sea. (5) She explained that rising water temperatures can harm the reefs. (6) She has written an article called Saving Our Reefs for a science magazine. (7) Her advice to students is simple: “Stay curious, and never stop asking questions.”"],"intro":"Aseel interviewed a scientist for the school newspaper. Her draft has some mistakes. Read it and answer the questions."}]};
(function(d){d.units.forEach(function(u){u.sets.forEach(function(s){s.passage=s.p==null?null:d.pass[s.p];});});})(window.MAP_DATA["language_7"]);
